use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts days since 1970-01-01 (UTC) to a proleptic Gregorian (year, month, day).
/// Howard Hinnant's `civil_from_days` algorithm.
fn civil_from_days(days: i64) -> (i64, i64, i64) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // Read the clock once so the date and the start instant describe the same moment.
        let now = wall_clock::now();
        let secs = now.seconds;

        let days = (secs / 86_400) as i64;
        let (y, m, d) = civil_from_days(days);

        RunInfo {
            // Always YYYY-MM-DD: 4-digit year, 2-digit month and day, so len == 10
            // for any year in 0000..=9999.
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started: secs,
        }
    }
}

export!(Node);
